import json
import subprocess
import threading
import time
from queue import Queue
from typing import List, Dict, Any

def run_command(command: str, name: str) -> Dict[str, Any]:
    start_time = time.time()
    result = subprocess.run(
        command,
        shell=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True
    )
    duration = round(time.time() - start_time, 2)
    return {
        'name': name,
        'command': command,
        'exit_code': result.returncode,
        'duration': duration,
        'stdout': result.stdout.strip(),
        'stderr': result.stderr.strip()
    }

def worker(command_queue: Queue, results: List[Dict[str, Any]], concurrency: int):
    while True:
        try:
            job = command_queue.get_nowait()
        except:
            break
        result = run_command(job['command'], job['name'])
        results.append(result)
        command_queue.task_done()

def generate_html(report_data: List[Dict[str, Any]], output_file: str):
    html = f"""<!DOCTYPE html>
<html>
<head>
    <title>Commands report</title>
    <style>
        table {{
            border-collapse: collapse;
            width: 100%;
        }}
        th, td {{
            border: 1px solid #ddd;
            padding: 8px;
            text-align: left;
        }}
        th {{
            background-color: #f2f2f2;
        }}
    </style>
</head>
<body>
    <table>
        <tr>
            <th>Name</th>
            <th>Command</th>
            <th>Exit code</th>
            <th>Duration (s)</th>
            <th>Stdout</th>
            <th>Stderr</th>
        </tr>
"""
    for job in report_data:
        html += f"""        <tr>
            <td>{job['name']}</td>
            <td>{job['command']}</td>
            <td>{job['exit_code']}</td>
            <td>{job['duration']}</td>
            <td>{html_escape(job['stdout'])}</td>
            <td>{html_escape(job['stderr'])}</td>
        </tr>
"""
    html += """    </table>
</body>
</html>
"""
    with open(output_file, 'w') as f:
        f.write(html)

def html_escape(text: str) -> str:
    escape_map = {
        '&': '&amp;',
        '"': '&quot;',
        "'": '&#39;',
        '<': '&lt;',
        '>': '&gt;'
    }
    return ''.join(escape_map.get(c, c) for c in text)

def main():
    import argparse
    parser = argparse.ArgumentParser()
    parser.add_argument('input_json', type=str)
    parser.add_argument('output_html', type=str)
    parser.add_argument('--concurrency', type=int, default=4)
    args = parser.parse_args()

    with open(args.input_json, 'r') as f:
        jobs = json.load(f)

    results = []
    command_queue = Queue()
    for job in jobs:
        command_queue.put(job)

    threads = []
    for _ in range(args.concurrency):
        t = threading.Thread(target=worker, args=(command_queue, results, args.concurrency))
        t.start()
        threads.append(t)

    command_queue.join()

    for t in threads:
        t.join()

    generate_html(results, args.output_html)

if __name__ == '__main__':
    main()

import json
import subprocess
import sys
import threading
import queue
from html import escape

def run_command(command, results_queue):
    try:
        result = subprocess.run(command, shell=True, check=False, text=True, capture_output=True)
        results_queue.put(('success', command, result.returncode, result.stdout, result.stderr))
    except Exception as e:
        results_queue.put(('error', command, -1, '', str(e)))

def worker(results_queue, jobs, index_queue):
    while True:
        try:
            job_index = index_queue.get_nowait()
            command = jobs[job_index]
            results_queue.put(('start', command, -1, '', ''))
            run_command(command, results_queue)
        except queue.Empty:
            break

