import sys
import subprocess
import concurrent.futures
import html

def run_command(command):
    try:
        result = subprocess.run(command, shell=True, check=False, text=True, capture_output=True)
        return command, result.returncode, result.stdout
    except Exception as e:
        return command, -1, str(e)

def process_commands(commands_file, report_file, concurrency=4):
    with open(commands_file, 'r') as f:
        commands = [line.strip() for line in f if line.strip()]

    results = []
    with concurrent.futures.ThreadPoolExecutor(max_workers=concurrency) as executor:
        futures = []
        for cmd in commands:
            futures.append(executor.submit(run_command, cmd))

        for future in concurrent.futures.as_completed(futures):
            results.append(future.result())

    # Reorder results to maintain input order
    ordered_results = []
    for cmd in commands:
        for res in results:
            if res[0] == cmd:
                ordered_results.append(res)
                break

    html_content = f"""<!DOCTYPE html>
<html>
<head>
    <title>Commands report</title>
    <style>
        table {{
            border-collapse: collapse;
            width: 100%;
        }}
        th, td {{
            border: 1px solid #dddddd;
            text-align: left;
            padding: 8px;
        }}
        th {{
            background-color: #f2f2f2;
        }}
    </style>
</head>
<body>
    <table>
        <tr>
            <th>Command</th>
            <th>Exit code</th>
            <th>Stdout</th>
        </tr>
"""
    for cmd, exit_code, stdout in ordered_results:
        html_content += f"""        <tr>
            <td>{html.escape(cmd)}</td>
            <td>{exit_code}</td>
            <td>{html.escape(stdout)}</td>
        </tr>
"""
    html_content += """
    </table>
</body>
</html>
"""

    with open(report_file, 'w') as f:
        f.write(html_content)

if __name__ == "__main__":
    if len(sys.argv) < 3:
        print("Usage: python report.py <commands.txt> <report.html> --concurrency <n>", file=sys.stderr)
        sys.exit(1)

    commands_file = sys.argv[1]
    report_file = sys.argv[2]
    concurrency = 4

    if len(sys.argv) == 5 and sys.argv[3] == "--concurrency":
        concurrency = int(sys.argv[4])

    process_commands(commands_file, report_file, concurrency)
    sys.exit(0)
